/* Google Search — Midnight (Zovo Styles starter) */
:root { color-scheme: dark; }
body, html { background: #0f1115 !important; color: #e6e6ea !important; }
#search, #rso, #center_col, #appbar { background: transparent !important; }
a, a:link { color: #8ab4f8 !important; }
a:visited { color: #b39ddb !important; }
input[type="text"], textarea, .gLFyf { background: #1c1f26 !important; color: #e6e6ea !important; border-color: #333945 !important; }
#searchform, header, nav { background: #0f1115 !important; }
div.g, .MjjYud { background: transparent !important; }
.hlcw0c, .cUnQKe, .wM6W7d { background: #161920 !important; }
#foot, #footer, .fbar { background: #161920 !important; }
img, video { opacity: .92; }

/* YouTube — Midnight (Zovo Styles starter) */
:root { color-scheme: dark; }
html[dark], body { background: #0b0d10 !important; }
ytd-app, ytd-watch-flexy, ytd-browse { background: #0b0d10 !important; color: #e8e8ec !important; }
#container.ytd-masthead, ytd-masthead { background: #0b0d10 !important; }
ytd-guide-renderer, #guide-wrapper { background: #101318 !important; }
.yt-spec-button-shape-next--filled, #search-input { background: #1a1e24 !important; color: #e8e8ec !important; }
a, .yt-formatted-string { color: inherit; }
.yt-core-attributed-string--link-inherit-color a { color: #9ec1ff !important; }
ytd-comment-thread-renderer, ytd-comments { background: transparent !important; }

/* GitHub — Dimmed Slate (Zovo Styles starter) */
:root { color-scheme: dark; }
body { background: #0d1117 !important; color: #c9d1d9 !important; }
.Header, .header-old { background: #161b22 !important; }
.Box, .box, .border { background: #161b22 !important; border-color: #2d333b !important; }
.markdown-body, .blob-wrapper { background: #0d1117 !important; color: #c9d1d9 !important; }
a, .Link--primary { color: #6cb6ff !important; }
.btn, .btn-primary { background: #21262d !important; color: #c9d1d9 !important; border-color: #373e47 !important; }

/* Reddit — Night Owl (Zovo Styles starter) */
:root { color-scheme: dark; }
body, shreddit-app { background: #0c0e12 !important; color: #e2e4e9 !important; }
#header, header { background: #12151b !important; }
shreddit-post, article, .Post { background: #12151b !important; }
a { color: #7aa7ff !important; }
button, input, textarea { color: #e2e4e9 !important; }
faceplate-panel, #right-sidebar-container { background: #0c0e12 !important; }

/* X — Midnight Blue (Zovo Styles starter) */
:root { color-scheme: dark; }
body { background: #0a1020 !important; color: #e7e9ea !important; }
main, [data-testid="primaryColumn"] { background: #0a1020 !important; }
header[role="banner"], nav { background: rgba(10,16,32,.92) !important; }
[data-testid="cellInnerDiv"] { background: transparent !important; }
a { color: #6ea8ff !important; }
[aria-label][role="button"] { color: inherit; }

/* Wikipedia — Night Paper (Zovo Styles starter) */
:root { color-scheme: dark; }
body, #content, .mw-body { background: #131418 !important; color: #e8e3d9 !important; }
.vector-header, .mw-page-container { background: #131418 !important; }
.mw-body-content a, a:link { color: #9db9e8 !important; }
a:visited { color: #b39ddb !important; }
.infobox, .navbox, table, .thumbinner { background: #1b1d22 !important; color: #e8e3d9 !important; border-color: #33363d !important; }
.mw-editsection, .toc { filter: brightness(.95); }

/* Stack Overflow — After Dark (Zovo Styles starter) */
:root { color-scheme: dark; }
body { background: #111418 !important; color: #d6d9dc !important; }
header, .top-bar { background: #181c20 !important; }
.question-summary, .s-post-summary, .post-layout { background: transparent !important; }
pre, code, .s-code-block { background: #1c2126 !important; color: #e3e6e8 !important; }
a, .s-link { color: #7fb3ff !important; }
.s-card, .sidebar, #sidebar { background: #15181d !important; border-color: #2b3138 !important; }

/* Amazon — Evening (Zovo Styles starter) */
:root { color-scheme: dark; }
body { background: #101317 !important; color: #e3e6e8 !important; }
#navbar, #nav-belt, #nav-main { background: #171c22 !important; }
.s-card-container, .a-cardui, .a-section { background: #15191f !important; color: #e3e6e8 !important; }
a, a:link { color: #7fb0e8 !important; }
input[type="text"], #twotabsearchtextbox { background: #1e242b !important; color: #e3e6e8 !important; }
